import * as T from 'three';
export const CLANS=[['crown','Little Royals'],['heart','Brave Hearts'],['star','Starlings'],['sun','Sunny Lions'],['moon','Moon Owls'],['flower','Petal Patrol'],['butterfly','Flutter Knights'],['leaf','Clover Keepers'],['cat','Kitten Guard'],['shell','Seashell Scouts']];
const material=c=>new T.MeshStandardMaterial({color:c,roughness:.64,metalness:.12});
export function clanShield(id='crown',color='#bd6489'){const g=new T.Group(),gold=material('#ddbd65'),cream=material('#fff0cb');function piece(geo,mat,x=0,y=0,z=.12){const m=new T.Mesh(geo,mat);m.position.set(x,y,z);m.castShadow=true;g.add(m);return m;}const base=piece(new T.CylinderGeometry(.5,.5,.10,32),gold,0,0,0);base.rotation.x=Math.PI/2;const disk=piece(new T.CylinderGeometry(.445,.445,.105,32),material(color),0,0,.018);disk.rotation.x=Math.PI/2;
const dot=(x,y,r=.055)=>piece(new T.SphereGeometry(r,10,6),cream,x,y,.11);const line=(x,y,w,h,rot=0)=>{const o=piece(new T.BoxGeometry(w,h,.065),cream,x,y,.11);o.rotation.z=rot;};const shape=points=>{const s=new T.Shape();points.forEach(([x,y],i)=>i?s.lineTo(x,y):s.moveTo(x,y));s.closePath();piece(new T.ExtrudeGeometry(s,{depth:.06,bevelEnabled:true,bevelThickness:.018,bevelSize:.012,bevelSegments:1,steps:1}),cream,0,0,.075);};
if(id==='crown'){shape([[-.29,-.16],[-.32,.16],[-.16,.04],[0,.28],[.16,.04],[.32,.16],[.29,-.16]]);for(const x of [-.32,0,.32])dot(x,x===0?.28:.16,.04);}else if(id==='heart'){const s=new T.Shape();s.moveTo(0,-.28);s.bezierCurveTo(-.6,.05,-.23,.43,0,.17);s.bezierCurveTo(.23,.43,.6,.05,0,-.28);piece(new T.ExtrudeGeometry(s,{depth:.06,bevelEnabled:true,bevelThickness:.012,bevelSize:.012,bevelSegments:1}),cream,0,0,.08);}else if(id==='star'){shape(Array.from({length:10},(_,i)=>{const a=i*Math.PI/5+Math.PI/2,r=i%2?.14:.33;return [Math.cos(a)*r,Math.sin(a)*r];}));}else if(id==='sun'){dot(0,0,.16);for(let i=0;i<8;i++){const a=i*Math.PI/4;line(Math.cos(a)*.28,Math.sin(a)*.28,.12,.04,a);}}else if(id==='moon'){shape(Array.from({length:17},(_,i)=>{const a=-Math.PI/2+i*Math.PI/16;return[-Math.cos(a)*.27,Math.sin(a)*.30];}).concat(Array.from({length:17},(_,i)=>{const a=Math.PI/2-i*Math.PI/16;return[-Math.cos(a)*.10,Math.sin(a)*.30];})));dot(.18,.17,.04);}else if(id==='flower'){for(let i=0;i<6;i++)dot(Math.cos(i*Math.PI/3)*.19,Math.sin(i*Math.PI/3)*.19,.11);piece(new T.SphereGeometry(.105,12,8),gold,0,0,.2);}else if(id==='butterfly'){for(const x of [-.15,.15]){const wing=dot(x,.08,.16);wing.scale.set(.8,1.2,.5);dot(x,-.14,.10);}line(0,0,.045,.4);}else if(id==='leaf'){shape([[0,-.28],[-.26,-.05],[-.23,.18],[0,.33],[.23,.18],[.26,-.05]]);line(0,-.02,.025,.39);}else if(id==='cat'){dot(0,-.02,.23);shape([[-.22,.08],[-.24,.32],[-.07,.17]]);shape([[.22,.08],[.24,.32],[.07,.17]]);const eyes=material('#63563c');for(const x of [-.08,.08])piece(new T.SphereGeometry(.025,8,6),eyes,x,.025,.34);}else {shape([[-.28,-.12],[-.31,.1],[-.19,.26],[0,.32],[.19,.26],[.31,.1],[.28,-.12],[.08,-.2],[-.08,-.2]]);for(const x of [-.15,0,.15]){const o=piece(new T.BoxGeometry(.018,.29,.025),gold,x*.7,.045,.17);o.rotation.z=-x*2;}}g.name=CLANS.find(c=>c[0]===id)?.[1]||'Clan shield';return g;}
